export function encode(input) {
  if (typeof input !== 'string') throw new TypeError('input must be a string');
  let out = '';
  let i = 0;
  while (i < input.length) {
    const ch = input[i];
    let run = 1;
    while (i + run < input.length && input[i + run] === ch) run += 1;
    out += `${run}x${ch}`;
    i += run;
  }
  return out;
}

export function decode(input) {
  if (typeof input !== 'string') throw new TypeError('input must be a string');
  let out = '';
  let i = 0;
  while (i < input.length) {
    let j = i;
    while (j < input.length && input[j] >= '0' && input[j] <= '9') j += 1;
    if (j === i) throw new SyntaxError('a run must start with a decimal digit');
    const digits = input.slice(i, j);
    if (digits.length > 1 && digits[0] === '0') throw new SyntaxError('a count has no leading zero');
    const count = Number(digits);
    if (count === 0) throw new SyntaxError('a count of zero is not valid');
    if (input[j] !== 'x') throw new SyntaxError('a count must be followed by x');
    if (j + 1 >= input.length) throw new SyntaxError('the x must be followed by a character');
    out += input[j + 1].repeat(count);
    i = j + 2;
  }
  return out;
}
